import java.util.*;
public class Johnson {
    // Johnson's: reweight using Bellman-Ford, then run Dijkstra from each vertex
    // Time: O(V^2 log V + VE) — better than Floyd-Warshall O(V^3) for sparse graphs
    static final int INF = Integer.MAX_VALUE/2;
    int n; int[][] dist;
    int[] bellmanFord(int[][] g) {
        int[] h = new int[n+1];
        Arrays.fill(h, INF); h[n] = 0;
        for(int i=0;i<n;i++) for(int u=0;u<=n;u++) for(int v=0;v<n;v++)
            if(g[u][v]!=INF&&h[u]!=INF) h[v]=Math.min(h[v],h[u]+g[u][v]);
        return h;
    }
    int[] dijkstra(int[][] g, int src, int[] h) {
        int[] d = new int[n]; Arrays.fill(d,INF); d[src]=0;
        PriorityQueue<int[]> pq=new PriorityQueue<>(Comparator.comparingInt(a->a[0]));
        pq.offer(new int[]{0,src});
        while(!pq.isEmpty()){int[]cur=pq.poll();int u=cur[1];if(cur[0]>d[u])continue;
            for(int v=0;v<n;v++) if(g[u][v]!=INF&&d[u]+g[u][v]<d[v]){d[v]=d[u]+g[u][v];pq.offer(new int[]{d[v],v});}}
        return d;
    }
}

